import { Log } from "@fanfanlo";
import { IProjectData } from "../project";
import { ITriggerActionGroup } from "../trigger-action/ITriggerActionGroup";
import { ITriggerAction } from "../trigger-action/ITriggerAction.intf";
import { IActionGroup } from "../action/IActionGroup.intf";
import { ITriggerGroup } from "../trigger/ITriggerGroup.intf";
import { IActionData, IActionJavaData, IActionShellData } from "../action/IAction.intf";
import { ITriggerData, ITriggerJavaData, ITriggerShellData } from "../trigger/ITrigger.intf";

const fileLog = new Log(false, 'description_entityFinder');
// fileLog.pause = true;
// fileLog.childrenPaused = true;

/**
 * 实体查找参数接口
 */
export interface IEntityFinderParams {
    projectClientId?: string
    triggerActionGroupId?: string
    triggerActionId?: string
    actionGroupId?: string
    actionId?: string
    triggerGroupId?: string
    triggerId?: string
}

/**
 * 实体类型
 */
export type EntityType =
    | 'project'
    | 'triggerActionGroup'
    | 'triggerAction'
    | 'actionGroup'
    | 'action'
    | 'triggerGroup'
    | 'trigger';

/**
 * 实体查找结果
 */
export interface IEntityFinderResult {
    entity: any
    type: EntityType
}

/**
 * 在TriggerActionGroup中查找TriggerAction
 */
function findInTriggerActionGroup(
    group: ITriggerActionGroup,
    id: string
): ITriggerAction | null {
    const fnLog = fileLog.sub(false, 'findInTriggerActionGroup_fn');
    // fnLog.pause = true;

    fnLog.log('开始查找TriggerAction, group:', group, 'id:', id);

    if (!group) {
        fnLog.log('group为null');
        return null;
    }

    if (!group.list) {
        fnLog.log('group.list为null');
        return null;
    }

    if (!Array.isArray(group.list)) {
        fnLog.log('group.list不是数组');
        return null;
    }

    const result = group.list.find(ta => ta.id === id) || null;
    fnLog.log('查找结果:', result);

    return result;
}

