import React, { useEffect, useState } from 'react';
import { Box, Typography, CircularProgress, IconButton } from '@mui/material';
import { useRouter } from 'next/router';
import { ArrowBack } from '@mui/icons-material';
import { Log } from "@fanfanlo";
import { AppShell, AppbarContainer, IAppbarProps } from "@app/ui";
import { projectStore } from '@droid/project-interface/storage/storage';
import { findEntityAcrossProjects, IEntityFinderParams, IEntityFinderResult } from '@droid/project-interface/utils/entityFinder';
import { IDescriptionContent } from '@droid/project-interface';
import { DescriptionContentRenderer } from '@droid/project-interface/components/description-renderer/DescriptionContentRenderer';
import { useTranslation } from '@fanfanlo';
import { TranslationComponent } from '@fanfanlo/translation';

const fileLog = new Log(false, 'DescriptionDetailPage_ui');
// fileLog.pause = true;
// fileLog.childrenPaused = true;

export default function DescriptionDetailPage() {
    const uiLog = fileLog.sub(false, 'DescriptionDetailPage_ui');
    // uiLog.pause = true;

    const { t } = useTranslation('homepage/pages/description-detail/content');

    const router = useRouter();
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [entityResult, setEntityResult] = useState<IEntityFinderResult | null>(null);
    const [descriptionContent, setDescriptionContent] = useState<IDescriptionContent | null>(null);
    const [entityName, setEntityName] = useState<string>('');

    useEffect(() => {
        const fnLog = uiLog.sub(false, 'effect_loadEntity_fn');
        // fnLog.pause = true;

        if (!router.isReady) {
            fnLog.log('router未准备好');
            return;
        }

        fnLog.log('开始加载实体, query:', router.query);

        const query = router.query;
        const field = query.field as string;

        if (!field) {
            fnLog.error('缺少field参数');
            setError(t('DescriptionDetailPage.missingField'));
            setLoading(false);
            return;
        }

        fnLog.log('field:', field);

        const params: IEntityFinderParams = {
            projectClientId: query.projectClientId as string,
            triggerActionGroupId: query.triggerActionGroupId as string,
            triggerActionId: query.triggerActionId as string,
            actionGroupId: query.actionGroupId as string,
            actionId: query.actionId as string,
            triggerGroupId: query.triggerGroupId as string,
            triggerId: query.triggerId as string
        };

        fnLog.log('查找参数:', params);

        const allProjects = [...projectStore.list, ...projectStore.draft];
        fnLog.log('所有projects数量:', allProjects.length);

        const result = findEntityAcrossProjects(allProjects, params);

        if (!result) {
            fnLog.error('未找到实体');
            setError(t('DescriptionDetailPage.entityNotFound'));
            setLoading(false);
            return;
        }

        fnLog.log('找到实体, type:', result.type, 'entity:', result.entity);

        setEntityResult(result);

        const entity = result.entity;

        if (!entity) {
            fnLog.error('entity为null');
            setError(t('DescriptionDetailPage.entityEmpty'));
            setLoading(false);
            return;
        }

        // 获取实体名字
        const name = entity.name || t('DescriptionDetailPage.unnamed');
        fnLog.log('实体名字:', name);
        setEntityName(name);

        // 获取描述内容
        let content: IDescriptionContent | null = null;

        if (field === 'summary') {
            content = entity.summary || null;
        } else if (field === 'fullIntroduction') {
            content = entity.fullIntroduction || null;
        } else {
            fnLog.error('未知的field:', field);
            setError(t('DescriptionDetailPage.unknownField', { field }));
            setLoading(false);
            return;
        }

        fnLog.log('描述内容:', content);

        if (!content) {
            fnLog.log('描述内容为空');
            const fieldName = field === 'summary'
                ? t('DescriptionDetailPage.summaryName')
                : t('DescriptionDetailPage.fullIntroductionName');
            setError(t('DescriptionDetailPage.noContent', { fieldName }));
            setLoading(false);
            return;
        }

        setDescriptionContent(content);
        setLoading(false);

    }, [router.isReady, router.query, t]);

    const handleBack = () => {
        const fnLog = uiLog.sub(false, 'handleBack_fn');
        // fnLog.pause = true;

        fnLog.log('返回上一页');
        router.back();
    };

    const appBarProps: IAppbarProps = {
        title: (
            <Box sx={{ display: 'flex', alignItems: 'center' }}>
                <IconButton onClick={handleBack} sx={{ mr: 1 }} data-testid="DescriptionDetailPage__backButton__01JG2B0090">
                    <ArrowBack />
                </IconButton>
                <Typography variant="h6">
                    {entityName} - {t('DescriptionDetailPage.detail')}
                </Typography>
            </Box>
        ),
        back: false
    };

    uiLog.log('渲染页面, loading:', loading, 'error:', error);

    return (
        <AppShell>
            <AppbarContainer appbarProps={appBarProps}>
                <Box sx={{ p: 3 }}>
                    {loading && (
                        <Box sx={{ display: 'flex', justifyContent: 'center', mt: 4 }}>
                            <CircularProgress />
                        </Box>
                    )}

                    {error && (
                        <Typography color="error">
                            {error}
                        </Typography>
                    )}

                    {!loading && !error && descriptionContent && (
                        <TranslationComponent sourceLang="auto">
                            <DescriptionContentRenderer data={descriptionContent} />
                        </TranslationComponent>
                    )}
                </Box>
            </AppbarContainer>
        </AppShell>
    );
}
